import{_ as s,o as i,c as e,a5 as t}from"./chunks/framework.C1a7WKBV.js";const k=JSON.parse('{"title":"Claude Code 全平台安装","description":"在 macOS、Windows、Linux 与 WSL 安装、登录和验证 Claude Code。","frontmatter":{"title":"Claude Code 全平台安装","description":"在 macOS、Windows、Linux 与 WSL 安装、登录和验证 Claude Code。"},"headers":[],"relativePath":"clients/claude-code.md","filePath":"clients/claude-code.md","lastUpdated":1788838685000}'),l={name:"clients/claude-code.md"};function n(h,a,p,d,o,r){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="claude-code-全平台安装" tabindex="-1">Claude Code 全平台安装 <a class="header-anchor" href="#claude-code-全平台安装" aria-label="Permalink to &quot;Claude Code 全平台安装&quot;">​</a></h1><p>本页优先使用官方原生安装器；只有原生安装器不可用、需要固定版本或已有 npm 工作流时，才使用包管理器或 npm。</p><h2 id="_1-官方原生安装器" tabindex="-1">1. 官方原生安装器 <a class="header-anchor" href="#_1-官方原生安装器" aria-label="Permalink to &quot;1. 官方原生安装器&quot;">​</a></h2><h3 id="_1-1-macos、linux-与-wsl" tabindex="-1">1.1 macOS、Linux 与 WSL <a class="header-anchor" href="#_1-1-macos、linux-与-wsl" aria-label="Permalink to &quot;1.1 macOS、Linux 与 WSL&quot;">​</a></h3><p>在终端中运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://claude.ai/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><p>安装结束后关闭当前终端，重新打开一个窗口。</p><h3 id="_1-2-windows-powershell" tabindex="-1">1.2 Windows PowerShell <a class="header-anchor" href="#_1-2-windows-powershell" aria-label="Permalink to &quot;1.2 Windows PowerShell&quot;">​</a></h3><p>以普通用户身份打开 PowerShell，不需要管理员权限：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">claude.ai</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div><h3 id="_1-3-windows-cmd" tabindex="-1">1.3 Windows CMD <a class="header-anchor" href="#_1-3-windows-cmd" aria-label="Permalink to &quot;1.3 Windows CMD&quot;">​</a></h3><p>在命令提示符中运行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>curl -fsSL https://claude.ai/install.cmd -o install.cmd &amp;&amp; install.cmd &amp;&amp; del install.cmd</span></span></code></pre></div><p>PowerShell 不支持这条 CMD 命令中的 <code>&amp;&amp;</code> 分隔符；CMD 也不识别 <code>irm</code>。请确认终端类型后复制对应命令。</p><h2 id="_2-验证与首次登录" tabindex="-1">2. 验证与首次登录 <a class="header-anchor" href="#_2-验证与首次登录" aria-label="Permalink to &quot;2. 验证与首次登录&quot;">​</a></h2><h3 id="_2-1-验证安装" tabindex="-1">2.1 验证安装 <a class="header-anchor" href="#_2-1-验证安装" aria-label="Permalink to &quot;2.1 验证安装&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>能看到版本号说明命令已经可用。<code>claude doctor</code> 会检查 PATH、认证、网络和更新状态，安装异常时优先运行它。</p><h3 id="_2-2-首次登录" tabindex="-1">2.2 首次登录 <a class="header-anchor" href="#_2-2-首次登录" aria-label="Permalink to &quot;2.2 首次登录&quot;">​</a></h3><p>进入一个项目目录后运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span></span></code></pre></div><p>命令会打开浏览器并引导登录。没有浏览器的环境可通过环境变量提供 API Key：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ANTHROPIC_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sk-ant-xxxxxxxx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span></span></code></pre></div><p>Windows PowerShell 使用下面的写法，关闭窗口后环境变量不会继续保留：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ANTHROPIC_API_KEY </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;sk-ant-xxxxxxxx&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">claude</span></span></code></pre></div><p>API Key 登录和浏览器登录选择其一即可；使用 STJAPI 令牌时，按 <a href="/ai-handbook/clients/cc-switch">CC Switch 对接 STJAPI</a> 完成供应商配置。不要把真实 API Key 或令牌写入项目文件，也不要提交到仓库。</p><h2 id="_3-平台补充安装方式" tabindex="-1">3. 平台补充安装方式 <a class="header-anchor" href="#_3-平台补充安装方式" aria-label="Permalink to &quot;3. 平台补充安装方式&quot;">​</a></h2><h3 id="_3-1-macos-homebrew" tabindex="-1">3.1 macOS Homebrew <a class="header-anchor" href="#_3-1-macos-homebrew" aria-label="Permalink to &quot;3.1 macOS Homebrew&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claude-code</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claude-code</span></span></code></pre></div><p>Homebrew 版本不会自动更新，需要按需执行升级命令。</p><h3 id="_3-2-windows-wsl-与-winget" tabindex="-1">3.2 Windows WSL 与 WinGet <a class="header-anchor" href="#_3-2-windows-wsl-与-winget" aria-label="Permalink to &quot;3.2 Windows WSL 与 WinGet&quot;">​</a></h3><p>需要 Linux 工具链或沙箱时，在管理员 PowerShell 中先安装 WSL：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">wsl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d Ubuntu</span></span></code></pre></div><p>打开 Ubuntu 后，按 macOS、Linux 的原生安装器步骤安装。习惯使用 WinGet 时也可以运行：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">winget install Anthropic.ClaudeCode</span></span></code></pre></div><h3 id="_3-3-linux-系统包管理器" tabindex="-1">3.3 Linux 系统包管理器 <a class="header-anchor" href="#_3-3-linux-系统包管理器" aria-label="Permalink to &quot;3.3 Linux 系统包管理器&quot;">​</a></h3><p>Debian、Ubuntu、Fedora、RHEL 和 Alpine 的官方仓库配置会随发行版变化。服务器环境优先查看 <a href="https://code.claude.com/docs/en/setup" target="_blank" rel="noreferrer">Claude Code 官方安装文档</a>，按当前发行版执行对应命令。</p><h2 id="_4-npm-备用安装" tabindex="-1">4. npm 备用安装 <a class="header-anchor" href="#_4-npm-备用安装" aria-label="Permalink to &quot;4. npm 备用安装&quot;">​</a></h2><p>只有原生安装器无法使用、需要固定版本或必须接入 npm 工作流时，才使用 npm。需要 Node.js 18 或更高版本：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @anthropic-ai/claude-code</span></span></code></pre></div><p>升级时：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @anthropic-ai/claude-code@latest</span></span></code></pre></div><p>不要使用 <code>sudo npm install -g</code>，这会使后续权限问题更难排查。</p><h2 id="_5-fnm-与-npm-镜像" tabindex="-1">5. fnm 与 npm 镜像 <a class="header-anchor" href="#_5-fnm-与-npm-镜像" aria-label="Permalink to &quot;5. fnm 与 npm 镜像&quot;">​</a></h2><p>没有 Node.js 或 npm 全局目录报权限错误时，可用 fnm 管理用户级 Node.js：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://fnm.vercel.app/install</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fnm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fnm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> use</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lts-latest</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fnm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lts-latest</span></span></code></pre></div><p>如果 npm 下载缓慢，设置镜像后再安装：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> registry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://registry.npmmirror.com</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @anthropic-ai/claude-code</span></span></code></pre></div><p>恢复官方源：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> registry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://registry.npmjs.org</span></span></code></pre></div><h2 id="_6-使用-stjapi" tabindex="-1">6. 使用 STJAPI <a class="header-anchor" href="#_6-使用-stjapi" aria-label="Permalink to &quot;6. 使用 STJAPI&quot;">​</a></h2><p>使用多供应商、账号切换或中转服务时，先安装 Claude Code，再按 <a href="/ai-handbook/clients/cc-switch">CC Switch 对接 STJAPI</a> 导入从 STJAPI 控制台创建的令牌。完成后在项目目录执行 <code>claude</code> 做一次简单验证。</p><p>验证时建议先使用低成本、短上下文的请求；确认响应正常后，再开始长对话或批量任务。</p><h2 id="_7-常见问题" tabindex="-1">7. 常见问题 <a class="header-anchor" href="#_7-常见问题" aria-label="Permalink to &quot;7. 常见问题&quot;">​</a></h2><h3 id="_7-1-claude-command-not-found" tabindex="-1">7.1 <code>claude: command not found</code> <a class="header-anchor" href="#_7-1-claude-command-not-found" aria-label="Permalink to &quot;7.1 \`claude: command not found\`&quot;">​</a></h3><p>关闭终端并重新打开；仍未解决时运行 <code>claude doctor</code>。npm 安装则检查 <code>npm config get prefix</code> 返回目录是否已加入 PATH。</p><h3 id="_7-2-npm-权限错误" tabindex="-1">7.2 npm 权限错误 <a class="header-anchor" href="#_7-2-npm-权限错误" aria-label="Permalink to &quot;7.2 npm 权限错误&quot;">​</a></h3><p>避免使用 sudo 安装。按第 5 节用 fnm 安装 Node.js 后，再在普通用户终端执行 npm 安装。</p><h3 id="_7-3-安装或登录网络异常" tabindex="-1">7.3 安装或登录网络异常 <a class="header-anchor" href="#_7-3-安装或登录网络异常" aria-label="Permalink to &quot;7.3 安装或登录网络异常&quot;">​</a></h3><p>先确认目标站点可以访问，并遵循 <a href="/ai-handbook/getting-started/stjapi">STJAPI 账户与网络设置</a> 中的直连检查。公司网络有 TLS 拦截时，需由网络管理员提供对应 CA 证书。</p><h2 id="_8-官方资料" tabindex="-1">8. 官方资料 <a class="header-anchor" href="#_8-官方资料" aria-label="Permalink to &quot;8. 官方资料&quot;">​</a></h2><ul><li><a href="https://code.claude.com/docs/en/setup" target="_blank" rel="noreferrer">Claude Code 安装文档</a></li><li><a href="https://code.claude.com/docs/en/quickstart" target="_blank" rel="noreferrer">Claude Code 快速入门</a></li><li><a href="https://code.claude.com/docs/en/troubleshoot-install" target="_blank" rel="noreferrer">安装故障排查</a></li></ul><p>装完之后的第一件事：跑通一次最小验证，然后按《<a href="/ai-handbook/tips/claude-code-advanced">Claude Code 进阶玩法</a>》把 Plan 模式和自定义命令用起来。</p>`,63)])])}const u=s(l,[["render",n]]);export{k as __pageData,u as default};
